	for i, tt := range tests {
		t.Run(strconv.Itoa(i)+"_"+tt.input, func(t *testing.T) {
			customCtx := *ctx
			customCtx.Precision = tt.sd
			customCtx.Rounding = tt.rm

			d, err := customCtx.New(tt.input)
			if err != nil {
				t.Fatalf("New(%q) error: %v", tt.input, err)
			}
			got := d.Sqrt().ValueOf()
			if got != tt.expected {
				t.Errorf("Decimal(%q).Sqrt() = %q, want %q", tt.input, got, tt.expected)
			}
		})
	}
